\label{thm:C}
    Given pairwise relatively prime positive integers $a$, $b$, and $c$, let $P(n)$ denote the number of solutions in nonnegative integers to $ax+by+cz=n$, for some positive integer $n$. Then there are quasi-polynomials $U(n)$ and $L(n)$ such that, for all positive integers $n$,
    \begin{enumerate}[label={\roman*.}\;]
        \item $L(n)\le P(n)\le U(n)$;
        \item $U(n)-L(n)\le\frac{a+b}{4}$; and
        \item $U(n)$ and $L(n)$ both have period $abc$.
    \end{enumerate}

Let $V\subset\mathbb{R}^k$ be a vector space. A subset $\Lambda\subset V$ is called a {\it lattice} if 
    \begin{enumerate}[label={\roman*.}\;]
         \item $\Lambda$ is an additive subgroup of $V$: for any $\vec{u},\vec{v}\in\Lambda$, $\vec{u}\pm\vec{v}\in\Lambda$;
         \item $\Lambda$ is {\it discrete}: for any bounded subset $B\subset V$, $B\cap\Lambda$ is finite; and
         \item $\Lambda$ spans $V$.
     \end{enumerate}

A {\it special triangle} in $\Lambda$ is a non-degenerate triangle $T$ whose vertices are integral points and such that $|\overset{\circ}{T}\cap\Lambda|=0$.
    A {\it triangulation} of a polygon $P\subset V$ is a planar graph $\Delta$ embedded in $V$ such that
    \begin{enumerate}[label={\roman*.}\;]
        \item $\Delta\subset P$;
        \item $\partial P\subset\Delta$;
        \item $P\setminus\Delta$ is a union of disjoint interiors of triangles.
    \end{enumerate}
    We call each complimentary component of $P\setminus\Delta$ a {\it face} of $\Delta$. A triangulation is called {\it special} if each face of $\Delta$ is the interior of a special triangle. Note that a special triangulation $\Delta$ of $P$ satisfies $(P\setminus\Delta)\cap\mathbb{Z}^k=\emptyset$.

\label{lem:P of a,b}
    Let $a,b\in\mathbb{Z}_{>0}$ with $d=\gcd(a,b)$. Then
    \begin{equation*}
        P_{\{a,b\}}(n)=\begin{cases}
        \frac{nd}{ab}-\left\{\frac{\beta n}{a}\right\}-\left\{\frac{\alpha n}{b}\right\}+1 & {\rm if}\;\;d|n\\
        \hspace{.5cm}0 & {\rm otherwise},
        \end{cases}
    \end{equation*}
    where $\beta\frac{b}{d}\equiv1\mod{\frac{a}{d}}$ and $\alpha\frac{a}{d}\equiv1\mod{\frac{b}{d}}$.

Using Equation \ref{eqn:recursive},
    \begin{equation*}
        P_{\{bc,ac,ab\}}(abc) = \overset{c}{\underset{i=0}{\sum}} P_{\{bc,ac\}}(abc - iab).
    \end{equation*}   
    \noindent Now, for the allotted values of $i$, $P_{\{bc,ac\}}(abc - iab) = 0$ if and only if $\gcd(bc,ac) \nmid abc- iab$.
    \noindent Assume that $\gcd(ac,bc) \nmid abc -iab$. Clearly, $\gcd(ac,bc)$ divides $abc$. So, it must be the case that $c\gcd(a,b) \nmid iab$. Dividing both sides by $\gcd(a,b)$ gives us $c \nmid i\,\textrm{lcm}(a,b)$.
    Let $\delta = \gcd(c, \textrm{lcm}(a,b))$. Then, $\frac{c}{\delta} \nmid i\frac{\textrm{lcm}(a,b)}{\delta}$ can be simplified to $\frac{c}{\delta} \nmid i$.
    To summarize, if $\frac{c}{\delta} \nmid i$, then $P_{\{bc,ac,ab\}}(abc)=0$. So, by assessing what values for $i$ allow $\frac{c}{\delta} | i$, we can find all values where $P_{\{bc,ac,ab\}}(abc)\neq0$. Clearly, $\frac{c}{\delta} | i$ for $i = 0, \frac{c}{\delta}, 2\frac{c}{\delta}, 3\frac{c}{\delta},...,\delta\frac{c}{\delta}$. Thus we have 
    $P_{\{bc,ac,ab\}}(abc)= \overset{\delta}{\underset{i=0}{\sum}} P_{\{bc,ac\}}(abc-i\frac{abc}{\delta})$.

    Let $d=\gcd(b,a)$. Then $\gcd(ac,bc)=cd$. Next, we apply Lemma \ref{lem:P of a,b}, which allows us to write\\ $\overset{\delta}{\underset{i=0}{\sum}} P_{\{bc,ac\}}\left(abc-i\frac{abc}{\delta}\right)$ as

    \begin{equation}\label{expr:pop} 
        \overset{\delta}{\underset{i=0}{\sum}} \left( \frac{\left(abc-i\frac{abc}{\delta}\right)cd}{bc(ac)} - \left\{ \frac{\beta\left(abc - i\frac{abc}{\delta}\right)}{bc}\right\} - \left\{ \frac{\alpha\left(abc - i\frac{abc}{\delta}\right)}{ac}\right\} +1 \right).
    \end{equation}
    where $\beta\frac{ac}{cd}\equiv1\,\text{mod}\,{\frac{bc}{cd}}$ and $\alpha\frac{bc}{cd}\equiv1\,\text{mod}\,\frac{ac}{cd}.$

    First, let us focus on the first term of Expression \ref{expr:pop}. 
    \begin{align*}
        \overset{\delta}{\underset{i=0}{\sum}} \frac{(abc-i\frac{abc}{\delta})cd}{bc(ac)} &= \overset{\delta}{\underset{i=0}{\sum}}\left(1-\frac{i}{\delta}\right) \gcd(b,a) \\
        &= \gcd(a,b)\left(\overset{\delta}{\underset{i=0}{\sum}}1-\overset{\delta}{\underset{i=0}{\sum}}\frac{i}{\delta}\right)\\
        &= \gcd(a,b)(\delta+1)-\frac{\gcd(a,b)(\delta+1)}{2}\\
        &= \frac{\gcd(a,b)(\delta+1)}{2}.
    \end{align*}
    Recall that $\delta = \gcd(c,\text{lcm}(a,b))$. Simplifying further we have,
    $$\frac{\gcd(a,b)(\delta +1)}{2} = \frac{\gcd(ac, bc, ab)}{2} + \frac{\gcd(a,b)}{2}.$$
    Thus, we have handled the first term of Expression \ref{expr:pop}.

    Now, we will consider the second term: $\overset{\delta}{\underset{i=0}{\sum}}\left\{ \frac{\beta\left(abc - i\frac{abc}{\delta}\right)}{bc}\right\}$. Note the definition of the fractional part of $\frac{\beta n}{a}$, 
    \begin{align*}
        \left \{\frac{\beta n}{a}\right\}&=\frac{\beta n}{a}- \left\lfloor\frac{\beta n}{a} \right\rfloor \\
        &= \frac{\beta n}{a} - \left( \frac{\beta n - \beta n\,\text{mod}\,a}{a}\right).
    \end{align*}
    Using this definition we can rewrite the second term of Expression \ref{expr:pop}.

    \begin{align*}
        \overset{\delta}{\underset{i=0}{\sum}}\left\{ \frac{\beta\left(abc - i\frac{abc}{\delta}\right)}{bc}\right\} &= \overset{\delta}{\underset{i=0}{\sum}}\left\{ \frac{\beta abc}{bc}- \frac{\beta \frac{abc}{\delta}i}{bc} \right\} \\
        &= \overset{\delta}{\underset{i=0}{\sum}} \left\{ \beta a - \frac{\beta a i}{\delta}\right\} .
    \end{align*}
     Note that whenever $\beta a - \frac{\beta ai}{\delta}$ is an integer, $\left\{ \beta a - \frac{\beta a i}{\delta}\right\} = 0$. So, we first break the sum into $\gcd(\beta a , \delta)$ sums, then we omit all terms that are equal to zero and apply the second portion of Lemma 2.8. This gives us,
    {\footnotesize\begin{align}\label{EQN:beakingsum}
        \overset{\delta}{\underset{i=0}{\sum}} \left\{ \beta a - \frac{\beta a i}{\delta}\right\}  &= \overset{\frac{\delta}{\gcd(\beta a, \delta)}}{\underset{i=0}{\sum}} \left\{ \beta a - \frac{\beta a i}{\delta}\right\} +\overset{2\frac{\delta}{\gcd(\beta a, \delta)}}{\underset{i=\frac{\delta}{\gcd(\beta a, \delta)}}{\sum}} \left\{ \beta a - \frac{\beta a i}{\delta}\right\}+\cdots+\overset{\delta}{\underset{i=\delta - \frac{\delta}{\gcd(\beta a, \delta)}}{\sum}} \left\{ \beta a - \frac{\beta a i}{\delta}\right\}\nonumber\\
        = &\overset{\frac{\delta}{\gcd(\beta a, \delta)}-1}{\underset{i=1}{\sum}} \left(1 - \left\{ \frac{\beta ai}{\delta}\right\}\right) +\overset{2\frac{\delta}{\gcd(\beta a, \delta)}-1}{\underset{i=\frac{\delta}{\gcd(\beta a, \delta)}+1}{\sum}} \left(1 - \left\{ \frac{\beta ai}{\delta}\right\}\right) +\cdots+\overset{\delta-1}{\underset{i=\delta - \frac{\delta}{\gcd(\beta a, \delta)}+1}{\sum}} \left(1 - \left\{ \frac{\beta ai}{\delta}\right\}\right).
    \end{align}}
    Since $i\equiv i+k\frac{\delta}{\gcd(\beta a,\delta)}\mod\frac{\delta}{\gcd(\beta a,\delta)}$ for any integer $k$, we can apply Lemma \ref{lem: fractional facts} and obtain
    \begin{equation*}
         \overset{\delta}{\underset{i=0}{\sum}} \left\{ \beta a - \frac{\beta a i}{\delta}\right\}=\gcd(\delta,\beta a)\sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1}\left(1 - \left \{ \frac{\beta ai}{\delta}\right \}\right).
    \end{equation*}
    Isolating the sum, we have
    \begin{equation*}
        \overset{\frac{\delta}{\gcd(\beta a, \delta)}-1}{\underset{i=1}{\sum}} 1 - \left \{ \frac{\beta ai}{\delta}\right \}
        = \overset{\frac{\delta}{\gcd(\beta a, \delta)}-1}{\underset{i=1}{\sum}} 1 - \frac{\beta ai\, \text{mod}\,\delta}{\delta}.
    \end{equation*}
    Now we factor out $\frac{-1}{\delta}$ from the second term so that we can work to further reduce the expression.
    \begin{align*}
        \sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1} 1 - \frac{\beta ai\, \text{mod}\,\delta}{\delta}
        &=\sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1} 1-\frac{1}{\delta}\sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1} \beta ai \, \text{mod}\,\delta \\
        &= \frac{\delta}{\gcd(\beta a, \delta)}-1 - \left( \frac{\gcd(\beta a , \delta)}{\gcd(\beta a , \delta)}\right)\frac{1}{\delta}\sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1} \beta ai\,\text{mod}\,\delta \\
        &= \frac{\delta}{\gcd(\beta a, \delta)}-1 - \gcd(\beta a,\delta)\frac{1}{\delta}\sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1} \frac{\beta ai}{\gcd(\beta a ,\delta)}\, \text{mod}\,\frac{\delta}{\gcd(\beta a , \delta)}.
    \end{align*}
    Since $\frac{\beta ai}{\gcd(\beta a ,\delta)}$ and $\text{mod}\frac{\delta}{\gcd(\beta a , \delta)}$ are relatively prime, this allows us to write
    \[
        \sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1}\frac{\beta ai}{\gcd(\beta a ,\delta)}\, \text{mod}\,\frac{\delta}{\gcd(\beta a , \delta)}=\sum_{i=1}^{\frac{\delta}{\gcd(\beta a, \delta)}-1}i=\frac{\left(\frac{\delta}{\gcd(\beta a ,\delta)}-1\right)\frac{\delta}{\gcd(\beta a ,\delta)}}{2}.
    \]
    Bringing it all together, 
    \begin{align*}
        \sum_{i=0}^\delta\left\{ \frac{\beta\left(abc - i\frac{abc}{\delta}\right)}{bc}\right\} &= \gcd(\beta a,\delta)\left( \frac{\delta}{\gcd(\beta a, \delta)}-1-\frac{\gcd(\beta a,\delta)}{\delta}\frac{\left(\frac{\delta}{\gcd(\beta a ,\delta)}-1\right)\frac{\delta}{\gcd(\beta a ,\delta)}}{2}\right)\\
        &=\frac{\delta}{2} - \frac{\gcd(\beta a,\delta)}{2}.
    \end{align*}

    For the third term of \ref{expr:pop}, $\overset{\delta}{\underset{i=0}{\sum}}\left\{ \frac{\alpha\left(abc - i\frac{abc}{\delta}\right)}{ac}\right\}$, the process will mirror the above and become $\frac{\delta}{2} - \frac{\gcd(\alpha b,\delta)}{2}$.

    Next, we must remove $\beta$ and $\alpha$ from the expressions $\frac{\delta}{2} - \frac{\gcd(\beta a,\delta)}{2}$ and $\frac{\delta}{2} - \frac{\gcd(\alpha b,\delta)}{2}$, respectively. We will do so by showing that $\gcd(\delta, \beta a) =\gcd(c,a)$ and $\gcd(\delta, \alpha b) =\gcd(c,b)$. First,
    recall that $\delta = \gcd(\text{lcm}(a,b),c)$ and the definitions of $\beta$, $\alpha$, and $d$ in our case are:
    \begin{align*}
        \beta \frac{ac}{cd} &\equiv   1\,\text{mod}\,\frac{bc}{cd} \hspace{2cm}  \alpha \frac{bc}{cd} \equiv   1\,\text{mod}\,\frac{ac}{cd} \hspace{2cm} 
        d = \gcd(a,b).
    \end{align*}
    Also, we know that $\beta \frac{ac}{cd} \equiv   1\text{mod}\frac{bc}{cd}$ implies that $\beta \frac{ac}{cd} = 1+ k\frac{bc}{cd}$ for some $k \in \mathbb{Z}$.
    \\

    Now, note that $\gcd(\delta, \beta a)=\gcd(\gcd(c,\text{lcm}(a,b)), \beta a)=\gcd(\gcd(c,(\text{lcm}(a,b),\beta a) $. Since $\beta a \equiv d \, \text{mod}\, b$, we have $\beta a = d + kb$ for some $k \in \mathbb{Z}$. Therefore,
    \begin{align*}
        \gcd(\delta, \beta a) &= \gcd\left(c,\gcd\left(\frac{ab}{d}, d+kb\right)\right) \\ 
        &= \gcd\left(c,\gcd\,d\left(\frac{a}{d}\frac{b}{d}, 1+k\frac{b}{d}\right)\right).
    \end{align*}
    We can see that $1+k\frac{b}{d}$ and $\frac{b}{d}$ are relatively prime. So,
    \begin{align*}
        \gcd\left(c,\gcd\,d\left(\frac{a}{d}\frac{b}{d}, 1+k\frac{b}{d}\right)\right) &= \gcd\left(c,\gcd\,d\left(\frac{a}{d}, 1+k\frac{b}{d}\right)\right) \\
        &= \gcd\left(c,\gcd\,d\left(\frac{a}{d}, \frac{\beta a }{d}\right)\right) \\
        &= \gcd\left(c,\gcd\,\left(a, \beta a\right)\right) \\
        &= \gcd(c,a).
    \end{align*}
    \noindent
    Thus, we have shown that $\gcd(\delta, \beta a) = \gcd(c,a)$, and by the same methods, $\gcd(\delta,\alpha b) = \gcd(c,b)$.
    \\
    Next, we can substitute these values into $\frac{\delta}{2}-\frac{\gcd(\beta a, \delta)}{2}$ and $\frac{\delta}{2}-\frac{\gcd(\alpha b, \delta)}{2}$, giving us $\frac{\delta}{2}-\frac{\gcd(c,a)}{2}$ and $\frac{\delta}{2}-\frac{\gcd(c,b)}{2}$, respectively. 

    Clearly, the final term of Expression \ref{expr:pop}, $\overset{\delta}{\underset{i=0}{\sum}} 1 = \delta +1$.

    Now that we have addressed all of the terms in \ref{expr:pop}, we can see the following:
    \begin{align*}
         P_{\{bc,ac,ab\}}(abc) 
         &= \sum_{i=0}^\delta\left(\frac{(abc-i\frac{abc}{\delta}) \gcd(bc,ac)}{bc(ac)} - \left\{ \frac{\beta(abc - i\frac{abc}{\delta})}{bc}\right\} - \left\{ \frac{\alpha(abc - i\frac{abc}{\delta})}{ac}\right\} +1 \right)\\
         &= \frac{\gcd(ac, bc, ab)}{2} + \frac{\gcd(a,b)}{2} - \left(\frac{\delta}{2}-\frac{\gcd(c,a)}{2}\right)-\left(\frac{\delta}{2}-\frac{\gcd(c,b)}{2}\right)+\delta +1 \\ 
         &= \frac{\gcd(ac, bc, ab)}{2} + \frac{\gcd(a,b)}{2}+\frac{ \gcd(c,a)}{2}+ \frac{\gcd(c,b)}{2} +1.
    \end{align*}

\label{rmk:Frob number}
    For pairwise relatively prime positive integers $a$, $b$, and $c$, let $N=N_{\{a,b,c\}}(n)$. The {\it $k$th Frobenius number}, a concept introduced in \cite{BeRo2004}, for $a$, $b$, and $c$ is the largest integer $n$ such that $P_{\{a,b,c\}}(n)=k$ ($k=0$ is the classical case). Then, for $n$ to be the $k$th Frobenius number of $a$, $b$, and $c$, by applying Equation \ref{eqn:gap bound} we must have
    \begin{equation}\label{eqn:Frob bounds}
        k+R_a+R_b+\frac{a+b}{4}-N\ge0,
    \end{equation}
    where $R_a=\frac{a-1}{2}\left\lfloor\frac{n}{ac}\right\rfloor+\frac{r_a(r_a+1)}{2a}$ and $R_b=\frac{b-1}{2}\left\lfloor\frac{n}{bc}\right\rfloor+\frac{r_b(r_b+1)}{2b}$. Now, $N$ is quadratic as a function of $n$, whereas all remaining terms are either linear functions of $n$ or bounded. It follows that the $k$th Frobenius number exists for any triple $a,b,c$ of pairwise relatively prime positive integers.

    This is by no means a new result. In fact, a number of bounds have been developed and exist in the literature. Recently, algorithms for computing upper and lower bounds can be found in \cite{TRIPATHI2017368}. Improvements on the algorithms contained therein are provided by \cite{suhajda2026frobeniusnumbervariables}. The upper bound obtained via Equation \ref{eqn:Frob bounds} is looser than those found in the aforementioned references.
